export function unequalAvPreviewFixture(audioSeconds: 2 | 10 = 10): File {
	const bytes = Uint8Array.from(inflateSync(Buffer.from((audioSeconds === 2 ? FILE_2 : FILE_10).join(''), 'base64')));
	assert.equal(createHash('sha256').update(bytes).digest('hex'), audioSeconds === 2 ? SHA256_2 : SHA256_10);
	return new File([bytes.buffer], 'Recording.mp4', { type: 'video/mp4' });
}
